import React from 'react';

function LiteratureReviewInput({ value, onChange, disabled }) {
  return (
    <section className="section">
      <h2 className="section-title">
        <span className="icon">📝</span>
        Literature Review
      </h2>
      <p className="section-description">
        Paste the full text of the literature review you want to analyze for hallucinations
        and citation accuracy.
      </p>
      <textarea
        className="literature-textarea"
        placeholder="Paste your literature review text here...&#10;&#10;Example: Recent advances in natural language processing have shown significant improvements in text generation (Smith et al., 2023). However, these models are prone to generating plausible-sounding but factually incorrect statements..."
        value={value}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        spellCheck={true}
      />
      <div className="char-count">
        {value.length} characters
        {value.length > 0 && value.length < 50 && (
          <span style={{ color: '#dc2626' }}> — minimum 50 required</span>
        )}
      </div>
    </section>
  );
}

export default LiteratureReviewInput;
